item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [3:0] x,
    output logic       f
);
    assign f = (~x[1] & ~x[3])
             | (x[2] & ~x[0])
             | (x[2] & x[3] & x[1]);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic [3:0] x;
    wire f;
    logic expected;
    logic [3:0] row_values;
    integer i;
    integer column_index;
    TopModule dut (.x(x), .f(f));
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            x = i[3:0];
            // Bits of each row list columns 00, 01, 11, 10, in that order.
            case ({x[2], x[3]})
                2'"'b00: row_values = 4'b1001;
                2'b01: row_values = 4'b0000;
                2'b11: row_values = 4'b0111;
                2'b10: row_values = 4'b1011;
            endcase
            case ({x[0], x[1]})
                2'b00: column_index = 0;
                2'b01: column_index = 1;
                2'b11: column_index = 2;
                2'b10: column_index = 3;
            endcase
            expected = row_values[column_index];
            #1;
            if (f "'!== expected)
                $fatal(1, "FAIL x=%b expected=%b actual=%b", x, expected, f);
        end
        $display("PASS: all 16 Karnaugh-map inputs matched");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
printf '"'%s\\n' \""'$compile_status" > compile_status.txt
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    printf '"'%s\\n' \""'$?" > simulation_status.txt
fi
cat compile.log simulation.log'

